import {
    geoPath,
    geoGraticule,
    GeoProjection,
    // geoDistance,
    geoOrthographic,
    geoMercator,
    geoConicEqualArea,
    geoConicEquidistant,
    geoEqualEarth,
    geoEquirectangular,
    geoGnomonic,
    geoConicConformal,
    geoStereographic,
} from 'd3-geo';
import { PROJECTION_TYPE } from '../../lib';
import { Implementation } from '..';
import worldMap from './worldMap110mLand.json';
export class WorldMapProjection {
    Implementation: Implementation;
    divHost: HTMLElement;

    // private listHashColor: HashColorInterface = {};
    public listShapes: Object;
    // public implmentation: Implmentation;
    width = 1000;
    height = 1000;
    mp: number[] = [0, 0];
    // tslint:disable-next-line:no-any
    geoGenerator: any;
    // tslint:disable-next-line:no-any
    projection: GeoProjection;
    yaw: number = 0;
    roll: number = -21;
    ctx: CanvasRenderingContext2D;
    options = {
        MERCATOR: geoMercator(),
        // ORTHOGRAPHIC: geoOrthographic(),
        CONIC_EQUAL_AREA: geoConicEqualArea(),
        CONIC_EQUI_DISTANT: geoConicEquidistant(),
        EQUAL_EARTH: geoEqualEarth(),
        EQUI_RECTANGULAR: geoEquirectangular(),
        GNOMONIC: geoGnomonic(),
        CONIC_CONFORMAL: geoConicConformal(),
        STEREO_GRAPHIC: geoStereographic(),
        ORTHOGRAPHIC: geoOrthographic()
            .scale(300)
            .translate([487.5, 350]),
    };
    // tslint:disable-next-line:no-any
    geojson: any;
    data: any;
    clickNum = 0;
    prevent: boolean;
    delay: number = 250;
    timer: NodeJS.Timer | number;
    press: boolean = false;
    mousePre: number[] = [0, 0];
    constructor(Implementation: Implementation) {
        this.Implementation = Implementation;
        this.listShapes = {};
        this.InitUI();
        this.InitCanvas();
        this.Init();
    }
    public InitUI() {
        const div = document.createElement('div');
        // div.style.background = '#dddddd';
        div.style.position = 'absolute';
        div.style.left = '40px';
        // div.style.color = '#ffffff';

        let t = document.createElement('p');
        t.textContent = 'World Map Projection';
        div.append(t);

        t = document.createElement('p');
        t.textContent = '* drag to pan';
        t.style.marginTop = '0px';
        t.style.marginBottom = '0px';
        // t.style.color = this.col[0];
        div.append(t);

        t = document.createElement('p');
        t.style.marginTop = '0px';
        t.style.marginBottom = '0px';
        // t.style.color = this.col[1];
        t.textContent = '* double click to shfit the projection';
        div.append(t);
        this.Implementation.divHost.append(div);
    }
    private InitCanvas() {
        const canvas = document.createElement('canvas');
        canvas.width = 1000; // this.implmentation.implementation.div.style.width;
        canvas.height = 1000; // this.implmentation.implementation.div.style.height;
        this.Implementation.divHost.append(canvas);
        const ctx = canvas.getContext('2d');
        if (ctx) {
            this.ctx = ctx;
            this.AppendEvent(canvas);
        }
    }
    public AppendEvent(ele: HTMLElement) {
        ele.onclick = (e: MouseEvent) => {
            this.prevent = false;
            this.timer = setTimeout(
                () => {
                    if (!this.prevent) {
                        // this.MouseClick(e);
                    }
                    this.prevent = false;
                },
                this.delay);
        };
        ele.ondblclick = (e: MouseEvent) => {
            clearTimeout(this.timer as number);
            this.prevent = true;
            this.MouseDoubleClick();
        };
        ele.onmousedown = (e: MouseEvent) => { this.press = true; };
        ele.onmouseup = (e: MouseEvent) => { this.press = false; };
        ele.onmousemove = (e: MouseEvent) => { this.MouseMove(e.offsetX, e.offsetY); };
        // ele.addEventListener('wheel', (e: WheelEvent) => this.MouseWheel(e, e.deltaY));
    }
    public MouseMove(x: number, y: number) {
        if (this.press) {
            this.MouseDrag(x, y);
            // return;
        }
        this.mp[0] = x;
        this.mp[1] = y;
        this.mousePre[0] = x;
        this.mousePre[1] = y;
    }
    public MouseDrag(x: number, y: number) {
        this.yaw += (x - this.mousePre[0]) * 0.53;
        this.roll -= (y - this.mousePre[1]) * 0.53;
        // this.mousePre[0] = x;
        // this.mousePre[1] = y;
    }
    public MouseDoubleClick() {
        this.clickNum++;
        if (this.clickNum % 6 === 0) {
            this.projection = geoMercator();
        } else if (this.clickNum % 6 === 1) {
            this.projection = geoConicEquidistant();
        } else if (this.clickNum % 6 === 2) {
            this.projection = geoConicEqualArea();
        } else if (this.clickNum % 6 === 3) {
            this.projection = geoConicConformal();
        } else if (this.clickNum % 6 === 4) {
            this.projection = geoStereographic();
        } else if (this.clickNum % 6 === 5) {
            this.projection = geoOrthographic()
                .scale(300)
                .translate([487.5, 350]);
        }
        // geoEquirectangular
        this.geoGenerator = geoPath()
            .projection(this.projection)
            .pointRadius(4)
            .context(this.ctx);
    }
    async Init() {
        this.geojson = worldMap;
        // https://blockbuilder.org/macsj200/0e8584f0e6b95d5924bd79fcc1163a6c
        // this.projection: GeoConicProjection = geoAlbers()
        // .translate([this.width / 2, this.height / 2]) // translate to center of screen
        // .scale(1000); // scale things down so see entire US
        // this.projection = geoOrthographic().scale(300).translate([487.5, 350]);
        // this.projection = geoAlbersUsa().scale(1300).translate([487.5, 305]);
        // Define path generator // path generator that will convert GeoJSON to SVG paths
        // let path = geoPath().projection(this.projection); // tell path generator to use albersUsa projection
        // console.log(path);
        this.projection = this.options[PROJECTION_TYPE.EQUAL_EARTH];
        this.geoGenerator = geoPath()
            .projection(this.projection)
            .pointRadius(4)
            .context(this.ctx);
        this.Update();
    }
    public Dispose() {
        // this.isRemoved = true;
        // this.definition.expressMapping.implementation.div.childNodes.forEach((e: HTMLElement) => {
        //     this.definition.expressMapping.implementation.div.removeChild(e);
        // });
    }
    public Update() {
        requestAnimationFrame(() => {
            // if (this.isRemoved) {return; }
            this.Update();
        });
        this.ctx.clearRect(0, 0, this.ctx.canvas.width, this.ctx.canvas.height);
        // Graticule
        let graticule = geoGraticule();
        this.ctx.beginPath();
        this.ctx.strokeStyle = '#eee';
        this.geoGenerator(graticule());
        this.ctx.strokeStyle = '#bbbbbb';
        this.ctx.stroke();
        this.projection.rotate([this.yaw, this.roll]); // -45
        this.ctx.lineWidth = 0.5;
        this.ctx.strokeStyle = '#333';
        this.ctx.beginPath();
        this.geoGenerator({ type: 'FeatureCollection', features: this.geojson.features });
        // this.geoGenerator({type: 'GeometryCollection', features: this.topo.objects.states});
        // for (let i = 0; i < this.topo.objects.states.geometries.length; ++i) {
        // for (let j = 0 ; j < this.topo.objects.states.geometries[i].arcs.length; ++j) {
        // console.log(this.topo.objects.states.geometries[i].arcs[j]);
        // }
        // }
        this.ctx.stroke();
        const p = this.projection([this.mp[0], this.mp[1]]);
        // console.log(p);
        this.ctx.beginPath();
        this.ctx.arc(this.mp[0], this.mp[1], 10, 0, 3.14 * 2);
        this.ctx.closePath();
        this.ctx.fillStyle = '#ff0000';
        this.ctx.fill();
        if (p) {
            this.ctx.beginPath();
            this.ctx.arc(p[0], p[1], 10, 0, 3.14 * 2);
            this.ctx.closePath();
            this.ctx.fillStyle = '#00ff00';
            this.ctx.fill();
        }
        // this.VisData();
        // this.yaw -= 0.2;
        // console.log(this.yaw);
    }
    public UpdateProjection() {
        this.geoGenerator = geoPath()
            .projection(this.projection)
            .pointRadius(4)
            .context(this.ctx);
    }
    // GetPro() {
    // λ *= 180 / Math.PI, φ *= 180 / Math.PI;
    // var p0 = projection0([λ, φ]), p1 = projection1([λ, φ]);
    // return [(1 - t) * p0[0] + t * p1[0], (1 - t) * -p0[1] + t * -p1[1]];
    // }
    // }
    // MouseEventController(e: MouseEventData): void {
    // this.
    // // TODO
    // }
}

